# compute 4/8-neighbor components for demo2 and test panels from manually transcribed positions
def comps(coords, diag=False):
    S=set(coords); out=[]
    while S:
        seed=S.pop(); stack=[seed]; comp={seed}
        while stack:
            r,c=stack.pop()
            ds=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
            for dr,dc in ds:
                p=(r+dr,c+dc)
                if p in S: S.remove(p);comp.add(p);stack.append(p)
        out.append(sorted(comp))
    return sorted(out,key=len,reverse=True)
